void CheckFogThinsIntoFoglessClassicLight(const FogData& data)
{
    const Config cfg = {};
    const Vec3 foglessBlastedLandsLight19 = {-12041.6f, -2450.3f, 0.0f};
    const float afterNoon = 0.5212f;
    const Vec3 toSun = {0.106f, 0.106f, 0.989f};
    const float offsets[] = {0.0f, -455.0f, -465.0f};
    FrameInputs frames[3];
    AuthoredFog fogs[3] = {};
    FogParams params[3];
    bool resolved = true;
    for (int i = 0; i < 3; ++i)
    {
        frames[i] = ContinentFrame(kEasternKingdoms, Add(foglessBlastedLandsLight19, {0, offsets[i], 20.0f}),
                                   afterNoon, toSun, false);
        resolved = data.Resolve(kEasternKingdoms, frames[i].camPos, afterNoon, kClearWeather, fogs[i]) && resolved;
        params[i] = BuildFogParams(frames[i], cfg, &fogs[i]);
    }
    const float innerOpacity = SunlitLevelRayOpacity(params[1], frames[1].camPos[2], 450.0f);
    const float outerOpacity = SunlitLevelRayOpacity(params[2], frames[2].camPos[2], 450.0f);
    std::printf("     light 19 at noon: centre scene density %.6f, distance fog %.6f; light 19 weight %.2f / %.2f, "
                "opacity at 450 yd %.3f / %.3f\n",
                SceneLayersDensity(params[0]), params[0].layers[kDistanceFogLayer].density,
                WeightOf(fogs[1], kFoglessBlastedLandsLight), WeightOf(fogs[2], kFoglessBlastedLandsLight),
                innerOpacity, outerOpacity);
    Check(resolved && std::fabs(innerOpacity - outerOpacity) < 0.08f,
          "fog thins continuously into a Classic light without fog");
    Check(Near(WeightOf(fogs[0], kFoglessBlastedLandsLight), 1.0f) && SceneLayersDensity(params[0]) == 0.0f &&
              params[0].layers[kDistanceFogLayer].density > 0.0f,
          "inside a Classic light without fog only the distance fog hides the far clip");
}

float DriftNoiseAt(const DriftNoiseLevel& level, int x, int y, int z, int channel)
{
    return DriftNoiseChannel(level.argb[(static_cast<size_t>(z) * level.size + y) * level.size + x], channel);
}

void CheckDriftNoise()
{
    const std::vector<DriftNoiseLevel> levels = BuildDriftNoise();
    bool meansHeld = !levels.empty() && levels.front().size == kDriftNoiseSize && levels.back().size == 1;
    float worstMean = 0.5f;
    for (const DriftNoiseLevel& level : levels)
        for (int channel = 0; channel < kDriftChannels; ++channel)
        {
            const float mean = DriftNoiseMean(level, channel);
            if (std::fabs(mean - 0.5f) > std::fabs(worstMean - 0.5f))
                worstMean = mean;
            meansHeld = meansHeld && std::fabs(mean - 0.5f) < 0.02f;
        }
    const DriftNoiseLevel& top = levels.front();
    const int middle = top.size / 2;
    const int last = top.size - 1;
    const double texels = static_cast<double>(top.size) * top.size;
    bool seamlessAndVaried = true;
    std::printf("     drift noise: %zu levels, mean furthest from 0.5 is %.3f\n", levels.size(), worstMean);
    for (int channel : {kDriftCoarseChannel, kDriftFineChannel})
    {
        std::printf("     drift noise channel %d spread by level:", channel);
        for (const DriftNoiseLevel& level : levels)
        {
            double sum = 0.0;
            for (uint32_t texel : level.argb)
            {
                const double d = DriftNoiseChannel(texel, channel) - 0.5;
                sum += d * d;
            }
            std::printf(" %.3f", std::sqrt(sum / level.argb.size()));
        }
        std::printf("\n");
    }    for (int channel = 0; channel < kDriftChannels; ++channel)
    {
        double interiorStep = 0.0;
        double seamStep = 0.0;
        double spread = 0.0;
        for (int z = 0; z < top.size; ++z)
            for (int y = 0; y < top.size; ++y)
            {
                interiorStep += std::fabs(DriftNoiseAt(top, middle - 1, y, z, channel) -
                                          DriftNoiseAt(top, middle, y, z, channel));
                seamStep += std::fabs(DriftNoiseAt(top, last, y, z, channel) - DriftNoiseAt(top, 0, y, z, channel));
                spread += std::fabs(DriftNoiseAt(top, 0, y, z, channel) - 0.5f);
            }
        interiorStep /= texels;
        seamStep /= texels;
        spread /= texels;
        std::printf("     drift noise channel %d: neighbour step %.4f inside, %.4f across the tile seam; "
                    "mean deviation %.3f\n",
                    channel, interiorStep, seamStep, spread);
        seamlessAndVaried = seamlessAndVaried && seamStep < 1.5 * interiorStep + 0.002 && spread > 0.05;
    }
    Check(meansHeld, "drift noise: every mip level averages 0.5 in every channel, so fog seen through long march "
                     "steps keeps its density");
    Check(seamlessAndVaried, "drift noise: patches, smoke and both swirl channels vary and tile without a seam");
}

void CheckLightHandover()
{
    const bool duskMoon = MoonLightsTheFog(false, -0.10f, 0.20f);
    const bool duskNeither = MoonLightsTheFog(false, -0.10f, -0.05f);
    const bool daySun = MoonLightsTheFog(false, 0.30f, 0.20f);
    const bool dawnSun = MoonLightsTheFog(true, 0.20f, -0.10f);
    const bool nightMoon = MoonLightsTheFog(true, -0.30f, 0.40f);
    const bool nightNeither = MoonLightsTheFog(true, -0.10f, -0.10f);
    Check(duskMoon && !duskNeither && !daySun && !dawnSun && nightMoon && nightNeither,
          "light handover: the moon lights the fog once it is up and the sun has set, and the sun once it is up "
          "and the moon has set; otherwise the client's day window decides");
}

