float DistanceFogOpacity(const FogParams& fog, float camZ, float distance)
{
    FogParams only = fog;
    for (int i = 0; i < kFogLayers; ++i)
        if (i != kDistanceFogLayer)
            only.layers[i].density = 0.0f;
    return SunlitLevelRayOpacity(only, camZ, distance);
}

void CheckDistanceFogFollowsTheView()
{
    const Vec3 arathi = {-2390.0f, -2409.0f, 60.0f};
    const Vec3 noon = {0.5f, 0.5f, 0.7f};
    const float liftedClip = 1277.0f;
    const float clientCap = 791.67f;
    FrameInputs rain = ContinentFrame(kEasternKingdoms, arathi, 0.5f, noon, false);
    rain.fogStart = -51.4f;
    rain.fogEnd = 769.5f;
    rain.zoneFogDistance = 769.5f;
    rain.farClip = liftedClip;
    rain.clientFarClip = clientCap;
    Config follows = {};
    Config yards = {};
    yards.farFogStretch = 0.0f;
    Config half = {};
    half.farFogStretch = 0.5f;
    const FogParams stretched = BuildFogParams(rain, follows, nullptr);
    const FogParams fixed = BuildFogParams(rain, yards, nullptr);
    const FogParams halfway = BuildFogParams(rain, half, nullptr);
    const float expected = 769.5f * liftedClip / clientCap;
    const float z = arathi.z;
    const float at800 = DistanceFogOpacity(stretched, z, 800.0f);
    const float at1200 = DistanceFogOpacity(stretched, z, 1200.0f);
    const float fixed800 = DistanceFogOpacity(fixed, z, 800.0f);
    const float fixed1200 = DistanceFogOpacity(fixed, z, 1200.0f);
    std::printf("     rain, fog end 769.5 yd, view 1277 of the client's 791.67: distance fog limit %.1f yd (%.1f "
                "expected), %.1f at FarFogStretch 0, %.1f at 0.5\n",
                stretched.farLimit, expected, fixed.farLimit, halfway.farLimit);
    std::printf("     distance fog opacity at 800 / 1200 yd: %.3f / %.3f; ending at the zone's fog end %.3f / %.3f\n",
                at800, at1200, fixed800, fixed1200);
    Check(std::fabs(stretched.farLimit - expected) < 0.5f &&
              std::fabs(stretched.layers[kDistanceFogLayer].endDistance - expected) < 0.5f,
          "distance fog: with the view lifted past the client's cap, the fog reaches as much further as the view");
    const float halfwayExpected = 769.5f * (1.0f + 0.5f * (expected / 769.5f - 1.0f));
    Check(Near(fixed.farLimit, 769.5f) && std::fabs(halfway.farLimit - halfwayExpected) < 0.5f,
          "distance fog: FarFogStretch 0 keeps the zone's fog end in yards, 0.5 goes halfway");
    Check(fixed1200 - fixed800 < 0.002f && fixed800 > 0.94f && at800 < 0.8f * fixed800 && at1200 - at800 > 0.1f,
          "distance fog: land between the zone's fog end and the view's end keeps its distance instead of one flat "
          "fog colour");
    const float fixedAtLimit = DistanceFogOpacity(fixed, z, fixed.farLimit);
    const float stretchedAtLimit = DistanceFogOpacity(stretched, z, stretched.farLimit);
    std::printf("     distance fog opacity at its limit: %.4f stretched, %.4f at the zone's fog end\n", stretchedAtLimit,
                fixedAtLimit);
    Check(std::fabs(stretchedAtLimit - fixedAtLimit) < 0.01f,
          "distance fog: stretched, it is as thick at its end as it was at the zone's fog end");

    FrameInputs unlifted = rain;
    unlifted.farClip = clientCap;
    FrameInputs noHook = rain;
    noHook.clientFarClip = 0.0f;
    FrameInputs belowCap = rain;
    belowCap.clientFarClip = 1400.0f;
    const FogParams unliftedFog = BuildFogParams(unlifted, follows, nullptr);
    const FogParams noHookFog = BuildFogParams(noHook, follows, nullptr);
    const FogParams belowCapFog = BuildFogParams(belowCap, follows, nullptr);
    FrameInputs unliftedYards = unlifted;
    const FogParams unliftedFixed = BuildFogParams(unliftedYards, yards, nullptr);
    const FogLayer& a = unliftedFog.layers[kDistanceFogLayer];
    const FogLayer& b = unliftedFixed.layers[kDistanceFogLayer];
    std::printf("     limit with the view at the client's cap %.1f, without the far clip hook %.1f, with a client cap "
                "past the view %.1f\n",
                unliftedFog.farLimit, noHookFog.farLimit, belowCapFog.farLimit);
    Check(Near(unliftedFog.farLimit, 769.5f) && a.start == b.start && a.density == b.density &&
              a.endDistance == b.endDistance && Near(noHookFog.farLimit, 769.5f) &&
              Near(belowCapFog.farLimit, 769.5f),
          "distance fog: without a lifted view it is unchanged");

    FrameInputs clear = rain;
    clear.fogStart = 319.2f;
    clear.fogEnd = liftedClip;
    clear.zoneFogDistance = 1388.9f;
    FrameInputs foggy = rain;
    foggy.fogStart = -116.9f;
    foggy.fogEnd = 553.1f;
    foggy.zoneFogDistance = 553.1f;
    FrameInputs lateStart = rain;
    lateStart.fogStart = 150.0f;
    const FogParams clearFog = BuildFogParams(clear, follows, nullptr);
    const FogParams foggyFog = BuildFogParams(foggy, follows, nullptr);
    const FogParams lateFog = BuildFogParams(lateStart, follows, nullptr);
    const FogParams lateFixed = BuildFogParams(lateStart, yards, nullptr);
    std::printf("     clear (fog end 1277, zone 1388.9): limit %.1f; foggy zone (553.1): %.1f; fog start 150: %.1f "
                "stretched, %.1f in yards\n",
                clearFog.farLimit, foggyFog.farLimit, lateFog.layers[kDistanceFogLayer].start,
                lateFixed.layers[kDistanceFogLayer].start);
    Check(Near(clearFog.farLimit, liftedClip) && std::fabs(foggyFog.farLimit - 553.1f * liftedClip / clientCap) < 0.5f,
          "distance fog: never past the view's end, and a foggy zone keeps its share of the view");
    Check(std::fabs(lateFog.layers[kDistanceFogLayer].start - 150.0f * liftedClip / clientCap) < 0.5f &&
              Near(lateFixed.layers[kDistanceFogLayer].start, 150.0f),
          "distance fog: its start follows the view too");
}

