constexpr DWORD kCommentOfTwoTokens = 0x0002FFFEu;
constexpr DWORD kDefOfFiveTokens = 0x05000051u;
constexpr DWORD kDclOfTwoTokens = 0x0200001Fu;
constexpr DWORD kMovOfTwoTokens = 0x02000001u;
