struct ClientShadowScene
{
    Vec3 eye;
    float view[16];
    const float* proj;
    D3DVIEWPORT9 world;
    FrameInputs in;
    std::vector<SceneVertex> vertices;
    Mat4 cameraRotation;
    Mat4 projection[kLightMaps];
    Mat4 cameraToLight[kLightMaps];
    Mat4 lightViewProjection[kLightMaps];
    float terrainRows[kClientShadowRows * 4];
    float modelRows[kClientShadowRows * 4];
};

Mat4 BoxPlacement(const ClientCaster& c)
{
    Mat4 w = IdentityMat();
    const Vec3 size = Sub(c.high, c.low);
    const Vec3 origin = Sub(c.low, kClientShadowEye);
    w.m[0][0] = size.x;
    w.m[1][1] = size.y;
    w.m[2][2] = size.z;
    w.m[0][3] = origin.x;
    w.m[1][3] = origin.y;
    w.m[2][3] = origin.z;
    return w;
}

void ReceiverPair(float* rows, int pair, const Mat4& lightViewProjection)
{
    for (int r = 0; r < 3; ++r)
        for (int c = 0; c < 4; ++c)
            rows[(3 * pair + r) * 4 + c] = (r == 1 ? -1.0f : 1.0f) * lightViewProjection.m[r][c];
}

ClientShadowScene MakeClientShadowScene(const float* proj, const D3DVIEWPORT9& world, Vec3 toLight)
{
    ClientShadowScene s = {};
    s.eye = Add(kClientShadowEye, kGameLikeWorldOffset);
    const Vec3 at = Add(kClientShadowTarget, kGameLikeWorldOffset);
    CameraRelativeLookAt(s.eye, at, s.view);
    s.proj = proj;
    s.world = world;
    s.in = MakeInputs(s.view, proj, s.eye, at, world);
    s.in.toLight[0] = toLight.x;
    s.in.toLight[1] = toLight.y;
    s.in.toLight[2] = toLight.z;
    s.in.sunElevation = toLight.z;
    AddQuad(s.vertices, {-2000, -2000, 0}, {2000, -2000, 0}, {2000, 2000, 0}, {-2000, 2000, 0}, kSceneGroundColour);
    for (const ClientCaster& c : kClientCasters)
        AddBox(s.vertices, c.low, c.high, 0xFF6E5A48);
    s.cameraRotation = IdentityMat();
    for (int i = 0; i < 3; ++i)
        for (int j = 0; j < 3; ++j)
            s.cameraRotation.m[i][j] = s.view[j * 4 + i];
    const Vec3 centres[kLightMaps] = {kNearMapCentre, kFarMapCentre, kCachedMapCentre};
    const float halves[kLightMaps] = {kNearMapHalfExtent, kFarMapHalfExtent, kNearMapHalfExtent};
    for (int map = 0; map < kLightMaps; ++map)
    {
        const Vec3 lightEye = Add(Sub(centres[map], kClientShadowEye),
                                  {toLight.x * kClientLightDistance, toLight.y * kClientLightDistance,
                                   toLight.z * kClientLightDistance});
        const Mat4 lightView = ViewFrom(lightEye, {-toLight.x, -toLight.y, -toLight.z}, kClientShadowLightUpHint);
        s.projection[map] = OrthoLh(halves[map], kClientLightDepthRange);
        s.cameraToLight[map] = Mul(lightView, AffineInverse(s.cameraRotation));
        s.lightViewProjection[map] = Mul(s.projection[map], s.cameraToLight[map]);
    }
    ReceiverPair(s.terrainRows, 0, s.lightViewProjection[0]);
    ReceiverPair(s.terrainRows, 1, s.lightViewProjection[1]);
    ReceiverPair(s.terrainRows, 2, s.lightViewProjection[2]);
    ReceiverPair(s.modelRows, 0, s.lightViewProjection[1]);
    ReceiverPair(s.modelRows, 1, s.lightViewProjection[0]);
    return s;
}

struct ClientShadowTestObjects
{
    IDirect3DVertexShader9* casterVs = nullptr;
    IDirect3DPixelShader9* casterPs = nullptr;
    IDirect3DVertexShader9* directVs = nullptr;
    IDirect3DPixelShader9* directPs = nullptr;
    IDirect3DVertexShader9* modelReceiverVs = nullptr;
    IDirect3DVertexShader9* terrainReceiverVs = nullptr;
    IDirect3DVertexDeclaration9* declaration = nullptr;
    IDirect3DVertexBuffer9* cube = nullptr;
    IDirect3DIndexBuffer9* cubeIndices = nullptr;
    IDirect3DTexture9* maps[kTestMaps] = {};
    IDirect3DSurface9* mapSurfaces[kTestMaps] = {};
    IDirect3DTexture9* colour = nullptr;
    IDirect3DSurface9* colourSurface = nullptr;
    IDirect3DTexture9* directColour = nullptr;
    IDirect3DSurface9* directColourSurface = nullptr;
    IDirect3DTexture9* oblongDepth = nullptr;
    IDirect3DSurface9* backBuffer = nullptr;
    IDirect3DSurface9* deviceDepth = nullptr;

    bool Create(IDirect3DDevice9* dev)
    {
        dev->CreateVertexShader(reinterpret_cast<const DWORD*>(g_vs_test_caster), &casterVs);
        dev->CreatePixelShader(reinterpret_cast<const DWORD*>(g_ps_test_caster), &casterPs);
        dev->CreateVertexShader(reinterpret_cast<const DWORD*>(g_vs_test_replay), &directVs);
        dev->CreatePixelShader(reinterpret_cast<const DWORD*>(g_ps_test_replay), &directPs);
        dev->CreateVertexShader(reinterpret_cast<const DWORD*>(g_vs_test_model_receiver), &modelReceiverVs);
        dev->CreateVertexShader(reinterpret_cast<const DWORD*>(g_vs_test_terrain_receiver), &terrainReceiverVs);
        dev->CreateVertexDeclaration(kReplayElements, &declaration);
        dev->CreateVertexBuffer(kCubeVertices * sizeof(ReplayVertex), D3DUSAGE_WRITEONLY, 0, D3DPOOL_MANAGED, &cube,
                                nullptr);
        dev->CreateIndexBuffer(kCubeTriangles * 3 * sizeof(WORD), D3DUSAGE_WRITEONLY, D3DFMT_INDEX16, D3DPOOL_MANAGED,
                               &cubeIndices, nullptr);
        const UINT sizes[kTestMaps] = {kClientMapSize, kClientMapSize, kClientDirectMapSize, kClientDirectMapSize};
        for (int i = 0; i < kTestMaps; ++i)
        {
            dev->CreateTexture(sizes[i], sizes[i], 1, D3DUSAGE_DEPTHSTENCIL, D3DFMT_D24X8, D3DPOOL_DEFAULT, &maps[i],
                               nullptr);
            if (maps[i])
                maps[i]->GetSurfaceLevel(0, &mapSurfaces[i]);
        }
        dev->CreateTexture(kClientMapSize, kClientMapSize, 1, D3DUSAGE_RENDERTARGET, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT,
                           &colour, nullptr);
        if (colour)
            colour->GetSurfaceLevel(0, &colourSurface);
        dev->CreateTexture(kClientDirectMapSize, kClientDirectMapSize, 1, D3DUSAGE_RENDERTARGET, D3DFMT_A8R8G8B8,
                           D3DPOOL_DEFAULT, &directColour, nullptr);
        if (directColour)
            directColour->GetSurfaceLevel(0, &directColourSurface);
        dev->CreateTexture(kClientDirectMapSize, kClientDirectMapSize / 2, 1, D3DUSAGE_DEPTHSTENCIL, D3DFMT_D24X8,
                           D3DPOOL_DEFAULT, &oblongDepth, nullptr);
        dev->GetBackBuffer(0, 0, D3DBACKBUFFER_TYPE_MONO, &backBuffer);
        dev->GetDepthStencilSurface(&deviceDepth);
        if (!casterVs || !casterPs || !directVs || !directPs || !modelReceiverVs || !terrainReceiverVs ||
            !declaration || !cube || !cubeIndices || !mapSurfaces[0] || !mapSurfaces[1] || !mapSurfaces[2] ||
            !mapSurfaces[kCachedMap] || !colourSurface || !directColourSurface || !oblongDepth || !backBuffer ||
            !deviceDepth)
            return false;
        dev->SetRenderTarget(0, directColourSurface);
        dev->SetDepthStencilSurface(mapSurfaces[kCachedMap]);
        dev->Clear(0, nullptr, D3DCLEAR_TARGET | D3DCLEAR_ZBUFFER, 0xFFFFFFFF, 1.0f, 0);
        dev->SetRenderTarget(0, backBuffer);
        dev->SetDepthStencilSurface(deviceDepth);
        void* p = nullptr;
        if (FAILED(cube->Lock(0, 0, &p, 0)))
            return false;
        auto* v = static_cast<ReplayVertex*>(p);
        for (UINT i = 0; i < kCubeVertices; ++i)
            v[i] = {(i & 1) ? 1.0f : 0.0f, (i & 2) ? 1.0f : 0.0f, (i & 4) ? 1.0f : 0.0f, 0, 0, 1, 0, 0};
        cube->Unlock();
        if (FAILED(cubeIndices->Lock(0, 0, &p, 0)))
            return false;
        const WORD indices[kCubeTriangles * 3] = {0, 1, 3, 0, 3, 2, 4, 6, 7, 4, 7, 5, 0, 4, 5, 0, 5, 1,
                                                  2, 3, 7, 2, 7, 6, 0, 2, 6, 0, 6, 4, 1, 5, 7, 1, 7, 3};
        std::memcpy(p, indices, sizeof(indices));
        cubeIndices->Unlock();
        return true;
    }

    void Release()
    {
        IUnknown* all[] = {casterVs,       casterPs,       directVs,       directPs,     modelReceiverVs,
                           terrainReceiverVs, declaration, cube,           cubeIndices,  mapSurfaces[0],
                           mapSurfaces[1], mapSurfaces[2], mapSurfaces[3], maps[0],      maps[1],
                           maps[2],        maps[3],
                           colourSurface,  colour,         directColourSurface, directColour, oblongDepth,
                           backBuffer,     deviceDepth};
        for (IUnknown* u : all)
            if (u)
                u->Release();
        *this = ClientShadowTestObjects();
    }
};

ULONG RefCount(IUnknown* u)
{
    u->AddRef();
    return u->Release();
}

void DrawDegenerateTriangle(IDirect3DDevice9* d)
{
    const ReplayVertex point[3] = {};
    d->DrawPrimitiveUP(D3DPT_TRIANGLELIST, 1, point, sizeof(ReplayVertex));
}

void BeginClientMap(IDirect3DDevice9* d, IDirect3DSurface9* colour, IDirect3DSurface9* depth, UINT size)
{
    d->SetRenderTarget(0, colour);
    d->SetDepthStencilSurface(depth);
    const D3DVIEWPORT9 vp = {0, 0, size, size, 0.0f, 1.0f};
    d->SetViewport(&vp);
    d->Clear(0, nullptr, D3DCLEAR_TARGET | D3DCLEAR_ZBUFFER, 0xFFFFFFFF, 1.0f, 0);
}

void DrawCasterWithAnotherMapsMatrices(IDirect3DDevice9* d, const ClientShadowTestObjects& o,
                                       const ClientShadowScene& s, int otherMap)
{
    float rows[16];
    Rows(s.projection[otherMap], rows, 4);
    d->SetVertexShaderConstantF(kCasterProjectionRegister, rows, 4);
    Rows(s.cameraToLight[otherMap], rows, 3);
    d->SetVertexShaderConstantF(kCasterCameraToLightRegister, rows, 3);
    DrawDegenerateTriangle(d);
    d->SetStreamSource(0, o.cube, 0, sizeof(ReplayVertex));
}

void DrawClientCasters(IDirect3DDevice9* d, const ClientShadowTestObjects& o, const ClientShadowScene& s, bool stray)
{
    d->SetVertexDeclaration(o.declaration);
    d->SetStreamSource(0, o.cube, 0, sizeof(ReplayVertex));
    d->SetIndices(o.cubeIndices);
    d->SetRenderState(D3DRS_ZENABLE, D3DZB_TRUE);
    d->SetRenderState(D3DRS_ZWRITEENABLE, TRUE);
    d->SetRenderState(D3DRS_ZFUNC, D3DCMP_LESSEQUAL);
    d->SetRenderState(D3DRS_CULLMODE, D3DCULL_NONE);
    d->SetRenderState(D3DRS_ALPHABLENDENABLE, FALSE);
    d->SetRenderState(D3DRS_ALPHATESTENABLE, FALSE);
    d->SetRenderState(D3DRS_STENCILENABLE, FALSE);
    d->SetRenderState(D3DRS_SCISSORTESTENABLE, FALSE);
    d->SetRenderState(D3DRS_COLORWRITEENABLE, 0xF);
    float rows[16];
    for (int map = 0; map < kCasterMaps; ++map)
    {
        BeginClientMap(d, o.colourSurface, o.mapSurfaces[map], kClientMapSize);
        d->SetVertexShader(o.casterVs);
        d->SetPixelShader(o.casterPs);
        Rows(s.projection[map], rows, 4);
        d->SetVertexShaderConstantF(kCasterProjectionRegister, rows, 4);
        Rows(s.cameraToLight[map], rows, 3);
        d->SetVertexShaderConstantF(kCasterCameraToLightRegister, rows, 3);
        for (const ClientCaster& c : kClientCasters)
        {
            if (map == 0 && !c.inNearMap)
                continue;
            Rows(Mul(s.cameraRotation, BoxPlacement(c)), rows, 3);
            d->SetVertexShaderConstantF(kWorldViewRegister, rows, 3);
            d->DrawIndexedPrimitive(D3DPT_TRIANGLELIST, 0, 0, kCubeVertices, 0, kCubeTriangles);
        }
        if (map == kFarMap)
            DrawCasterWithAnotherMapsMatrices(d, o, s, kNearMap);
    }
    BeginClientMap(d, o.directColourSurface, o.mapSurfaces[2], kClientDirectMapSize);
    d->SetVertexShader(o.directVs);
    d->SetPixelShader(o.directPs);
    Rows(s.projection[0], rows, 4);
    d->SetVertexShaderConstantF(kCasterProjectionRegister, rows, 4);
    Rows(Mul(s.cameraToLight[0], Mul(s.cameraRotation, BoxPlacement(kClientCasters[0]))), rows, 3);
    d->SetVertexShaderConstantF(kWorldViewRegister, rows, 3);
    d->DrawIndexedPrimitive(D3DPT_TRIANGLELIST, 0, 0, kCubeVertices, 0, kCubeTriangles);
    d->SetVertexShader(o.terrainReceiverVs);
    d->SetPixelShader(o.casterPs);
    DrawDegenerateTriangle(d);
    d->SetRenderTarget(0, o.backBuffer);
    d->SetDepthStencilSurface(o.deviceDepth);
    if (stray)
    {
        d->SetVertexShader(o.casterVs);
        d->SetPixelShader(o.casterPs);
        d->SetRenderState(D3DRS_ZENABLE, D3DZB_FALSE);
        d->SetRenderState(D3DRS_COLORWRITEENABLE, 0);
        DrawDegenerateTriangle(d);
        d->SetRenderState(D3DRS_COLORWRITEENABLE, 0xF);
        d->SetRenderState(D3DRS_ZENABLE, D3DZB_TRUE);
    }
}

void DrawClientReceivers(IDirect3DDevice9* d, const ClientShadowTestObjects& o, const ClientShadowScene& s,
                         bool terrain, bool models)
{
    d->SetVertexDeclaration(o.declaration);
    d->SetPixelShader(o.directPs);
    if (terrain)
    {
        d->SetTexture(kTerrainReceiverFirstStage, o.maps[0]);
        d->SetTexture(kTerrainReceiverFirstStage + 1, o.maps[1]);
        d->SetTexture(kTerrainReceiverFirstStage + 2, o.maps[kCachedMap]);
        d->SetTexture(kTerrainReceiverFirstStage + 3, o.colour);
        d->SetVertexShaderConstantF(kTerrainReceiverRegister, s.terrainRows, kClientShadowRows);
        d->SetVertexShader(o.terrainReceiverVs);
        DrawDegenerateTriangle(d);
    }
    if (models)
    {
        d->SetTexture(kModelReceiverFirstStage, o.maps[1]);
        d->SetTexture(kModelReceiverFirstStage + 1, o.maps[0]);
        d->SetTexture(kModelReceiverFirstStage + 2, o.colour);
        d->SetTexture(kModelReceiverFirstStage + 3, o.oblongDepth);
        d->SetVertexShaderConstantF(kModelReceiverRegister, s.modelRows, kClientShadowRows);
        d->SetVertexShader(o.modelReceiverVs);
        DrawDegenerateTriangle(d);
    }
    for (DWORD stage = kClientShadowFirstStage; stage < kClientShadowFirstStage + kClientShadowStages; ++stage)
        d->SetTexture(stage, nullptr);
}

struct ClientShadowFrameResult
{
    Image plain;
    Image shown;
    ULONG nearRefsInTheFrame = 0;
    ClientShadowStats inTheFrame = {};
    bool rendered = false;
    bool statesKept = false;
};

enum ClientFrameParts : unsigned
{
    kCasters = 1u,
    kStrayCaster = 2u,
    kTerrainReceivers = 4u,
    kModelReceivers = 8u,
    kEverything = 15u,
};

ClientShadowFrameResult DrawClientShadowFrame(Harness& h, const ClientShadowTestObjects& o, ClientShadowScene& s,
                                              unsigned parts)
{
    ClientShadowFrameResult r;
    h.BeginFrame();
    if (parts & kCasters)
        DrawClientCasters(h.dev, o, s, (parts & kStrayCaster) != 0);
    h.DrawVertices(s.eye, s.view, s.proj, s.world, s.vertices);
    DrawClientReceivers(h.dev, o, s, (parts & kTerrainReceivers) != 0, (parts & kModelReceivers) != 0);
    r.nearRefsInTheFrame = RefCount(o.maps[0]);
    vf_test_client_shadow_stats(&r.inTheFrame, 0);
    r.plain = Capture(h.dev);
    h.SetEngineState(s.world);
    Sentinel before;
    ReadSentinel(h.dev, before);
    const char* skip = "";
    r.rendered = vf_test_render(&s.in, &skip) != 0;
    Sentinel after;
    ReadSentinel(h.dev, after);
    r.statesKept = SameSentinel(before, after);
    if (!r.statesKept)
        ReportSentinelDifferences(before, after);
    ReleaseSentinel(before);
    ReleaseSentinel(after);
    r.shown = Capture(h.dev);
    h.dev->EndScene();
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    return r;
}

float TintError(const ClientShadowFrameResult& r, ScreenPoint p, const float* tint, float* measured)
{
    float worst = 0.0f;
    for (int c = 0; c < 3; ++c)
    {
        const int ch = 2 - c;
        measured[c] = BoxMean7x7(r.shown, p.x, p.y, ch) / std::fmax(BoxMean7x7(r.plain, p.x, p.y, ch), 1e-3f);
        worst = std::fmax(worst, std::fabs(measured[c] - tint[c]));
    }
    return worst;
}

bool TintsMatch(const ClientShadowFrameResult& r, const ClientShadowScene& s, const char* what, int column)
{
    bool ok = true;
    for (const TintProbe& probe : kTintProbes)
    {
        const float* tint = column == 0   ? probe.terrainReceivers
                            : column == 1 ? probe.modelReceiversOnly
                            : column == 2 ? probe.casters
                                          : kNoMapsTint;
        float measured[3];
        const ScreenPoint p = ProjectScenePoint(probe.point, s.eye, s.view, s.proj, s.world);
        const float error = TintError(r, p, tint, measured);
        std::printf("     %s, %s at %u,%u: %.2f %.2f %.2f (expected %.2f %.2f %.2f)\n", what, probe.name, p.x, p.y,
                    measured[0], measured[1], measured[2], tint[0], tint[1], tint[2]);
        ok = ok && error < kClientShadowTintTolerance;
    }
    const float unchanged[3] = {1.0f, 1.0f, 1.0f};
    float sky[3];
    const float skyError = TintError(r, kSkyAboveTheHorizon, unchanged, sky);
    std::printf("     %s, sky at %u,%u: %.2f %.2f %.2f (expected unchanged)\n", what, kSkyAboveTheHorizon.x,
                kSkyAboveTheHorizon.y, sky[0], sky[1], sky[2]);
    return ok && skyError < kClientShadowTintTolerance;
}

float MatrixDifference(const float* got, const Mat4& expected, int rows)
{
    float worst = 0.0f;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < 4; ++c)
            worst = std::fmax(worst, std::fabs(got[r * 4 + c] - expected.m[r][c]));
    return worst;
}

float RowsDifference(const float* got, const float* expected, int rows)
{
    float worst = 0.0f;
    for (int i = 0; i < rows * 4; ++i)
        worst = std::fmax(worst, std::fabs(got[i] - expected[i]));
    return worst;
}

std::vector<float> LoggedLightAngles(const std::string& line)
{
    std::vector<float> angles;
    for (size_t at = line.find(", light "); at != std::string::npos; at = line.find(", light ", at + 1))
        angles.push_back(static_cast<float>(std::atof(line.c_str() + at + 8)));
    return angles;
}

bool ReceiverRowsMatch(const std::string& line, const char* kind, const char* maps)
{
    const size_t at = line.find(kind);
    if (at == std::string::npos || line.find(maps, at) != at + std::strlen(kind) + 17)
        return false;
    const std::string match = ", rows match the casters' to ";
    const size_t rows = line.find(match, at);
    if (rows == std::string::npos)
        return false;
    char* end = nullptr;
    const double difference = std::strtod(line.c_str() + rows + match.size(), &end);
    return difference < kClientShadowMatrixTolerance && std::strncmp(end, " with y flipped", 15) == 0;
}

ClientShadowStats ClientShadowStatsAndReset()
{
    ClientShadowStats s = {};
    vf_test_client_shadow_stats(&s, 1);
    return s;
}

void SetClientShaderRoles(int role)
{
    vf_test_set_client_shader_role(Fnv1a(g_vs_test_caster, sizeof(g_vs_test_caster)),
                                   role ? kPaletteCasterRole : kNoRole);
    vf_test_set_client_shader_role(Fnv1a(g_ps_test_caster, sizeof(g_ps_test_caster)),
                                   role ? kCasterPixelRole : kNoRole);
    vf_test_set_client_shader_role(Fnv1a(g_vs_test_replay, sizeof(g_vs_test_replay)),
                                   role ? kDirectCasterRole : kNoRole);
}

unsigned ShaderReads(const BYTE* code, size_t size)
{
    return vf_test_client_shader_reads(reinterpret_cast<const DWORD*>(code), static_cast<unsigned>(size));
}

unsigned HandWrittenShaderReads(bool movFromC40)
{
    const DWORD code[] = {kVertexShader30Token,
                          kCommentOfTwoTokens, kMovOfTwoTokens, kSourceC224,
                          kDefOfFiveTokens, kDestinationC40, kFloatOne, 0, 0, 0,
                          kDclOfTwoTokens, kPositionUsage, kDestinationV0,
                          kMovOfTwoTokens, kDestinationR0, movFromC40 ? kSourceC40 : kSourceV0,
                          kEndToken};
    return vf_test_client_shader_reads(code, sizeof(code));
}

void CheckClientShaderClassification()
{
    const bool known = vf_test_client_shader_role(0xea99ea307a197a84ull) == kDirectCasterRole &&
                       vf_test_client_shader_role(0x202b452e580a7742ull) == kPaletteCasterRole &&
                       vf_test_client_shader_role(0x8535271f53b044b4ull) == kPaletteCasterRole &&
                       vf_test_client_shader_role(0x78641e03a615f46aull) == kCasterPixelRole &&
                       vf_test_client_shader_role(0x4f20b99325ed9c47ull) == kCasterPixelRole &&
                       vf_test_client_shader_role(0x86734e450fc6656eull) == kCasterPixelRole &&
                       vf_test_client_shader_role(Fnv1a(g_vs_test_caster, sizeof(g_vs_test_caster))) == kNoRole;
    Check(known, "client shadow maps: the client's shadow shaders from the 07:30 capture are known by their hashes");
    const unsigned model = ShaderReads(g_vs_test_model_receiver, sizeof(g_vs_test_model_receiver));
    const unsigned terrain = ShaderReads(g_vs_test_terrain_receiver, sizeof(g_vs_test_terrain_receiver));
    const unsigned caster = ShaderReads(g_vs_test_caster, sizeof(g_vs_test_caster));
    const unsigned replay = ShaderReads(g_vs_test_replay, sizeof(g_vs_test_replay));
    const unsigned pixel = ShaderReads(g_ps_test_caster, sizeof(g_ps_test_caster));
    const unsigned truncated = ShaderReads(g_vs_test_model_receiver, 3 * sizeof(DWORD));
    std::printf("     receiver rows read: model receiver %u, terrain receiver %u, caster %u, replay %u, pixel %u, "
                "cut short %u\n",
                model, terrain, caster, replay, pixel, truncated);
    Check(model == kReadsModelReceiverRows && terrain == kReadsTerrainReceiverRows && caster == 0 && replay == 0 &&
              pixel == 0 && truncated == 0,
          "client shadow maps: a vertex shader is a model receiver when it reads c224-235 and a terrain receiver "
          "when it reads c37-48");
    const unsigned declaresOnly = HandWrittenShaderReads(false);
    const unsigned movesFromC40 = HandWrittenShaderReads(true);
    std::printf("     hand-written vs_3_0 with c224 in a comment and def c40: reads %u; with a mov from c40 too: %u\n",
                declaresOnly, movesFromC40);
    Check(declaresOnly == 0 && movesFromC40 == kReadsTerrainReceiverRows,
          "client shadow maps: a register inside a comment block or set by def is not a read; a mov from it is");
}

void CheckClientShadowTrackerCost(Harness& h, const Config& on)
{
    LogTestObjects o;
    if (!o.Create(h.dev))
    {
        Check(false, "client shadow maps: timing objects created");
        o.Release();
        return;
    }
    SetTestConfig(&on);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    ClientShadowStatsAndReset();
    double wrapped = 0.0;
    double direct = 0.0;
    const double perDraw = WrapperNanosecondsPerDraw(h, o, wrapped, direct, 1);
    const ClientShadowStats s = ClientShadowStatsAndReset();
    std::printf("     %d draws with a constant, a render state and a texture each, ClientShadowMaps=1, no casters: "
                "%.3f ms through the wrapper, %.3f ms on the device itself, %.1f ns per draw; %u shaders "
                "classified, %u device queries\n",
                kLoggerTimingDraws, wrapped, direct, perDraw, s.shadersClassified, s.deviceQueries);
    Check(perDraw < kClientShadowTrackerNanosecondsPerDraw && s.shadersClassified == 2 && s.framesWithMaps == 0 &&
              s.heldTextures == 0,
          "ClientShadowMaps=1 with no shadow casters (extShadowQuality 0) adds less than 50 ns per draw and reads "
          "each shader once");
    o.Release();
}

void CheckClientShadowMaps(Harness& h, const Config& cfg, const float* proj, const D3DVIEWPORT9& world,
                           const std::wstring& outDir)
{
    Config start = {};
    vf_test_get_config(&start);
    CheckClientShaderClassification();

    Config off = cfg;
    off.density = 0.0f;
    off.temporal = 0.0f;
    off.terrainShadows = false;
    off.surfaceShadows = 0.0f;
    off.clientShadowMaps = false;
    off.debugView = 0;
    Config on = off;
    on.clientShadowMaps = true;
    CheckClientShadowTrackerCost(h, on);

    const Vec3 toLight = Norm({0.0f, 0.6f, 0.8f});
    ClientShadowScene s = MakeClientShadowScene(proj, world, toLight);
    ClientShadowTestObjects o;
    const bool created = o.Create(h.dev);
    Check(created, "client shadow test objects created: two 2048x2048 and one 1024x1024 D24X8 depth textures");
    if (!created)
    {
        o.Release();
        SetTestConfig(&start);
        return;
    }
    SetClientShaderRoles(1);

    SetTestConfig(&off);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    ClientShadowStatsAndReset();
    ClientShadowFrameResult offFrame;
    for (int frame = 0; frame < kClientShadowSettleFrames; ++frame)
        offFrame = DrawClientShadowFrame(h, o, s, kEverything);
    const ClientShadowStats idle = ClientShadowStatsAndReset();
    Check(idle.framesWatched == 0 && idle.shadersClassified == 0 && idle.deviceQueries == 0 &&
              idle.heldTextures == 0 && idle.debugPasses == 0 && offFrame.rendered,
          "with ClientShadowMaps=0 and DebugView below 7 the shadow-map tracker watches nothing and asks the device "
          "nothing, even while the client draws shadow maps");

    SetTestConfig(&on);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    ClientShadowStatsAndReset();
    const ULONG nearRefs = RefCount(o.maps[0]);
    const ClientShadowFrameResult first = DrawClientShadowFrame(h, o, s, kEverything);
    const ULONG nearRefsAfter = RefCount(o.maps[0]);
    char line[4096] = {};
    vf_test_client_shadow_log(line, sizeof(line));
    ClientShadowFrame f = {};
    vf_test_client_shadow_last_frame(&f);
    ClientShadowFrameResult onFrame = first;
    for (int frame = 1; frame < kClientShadowSettleFrames; ++frame)
        onFrame = DrawClientShadowFrame(h, o, s, kEverything);
    const ClientShadowStats watched = ClientShadowStatsAndReset();
    std::printf("%s\n", line);
    std::printf("     near map references %lu before the frame, %lu while it is drawn, %lu after Present; %u maps "
                "held in the frame, %u after; %u shaders read over %d frames\n",
                nearRefs, first.nearRefsInTheFrame, nearRefsAfter, first.inTheFrame.heldTextures,
                watched.heldTextures, watched.shadersClassified, kClientShadowSettleFrames);
    Check(watched.shadersClassified == kClientTestShaders && watched.framesWatched == kClientShadowSettleFrames,
          "client shadow maps: over three frames each of the six test shaders is read once, however often it is "
          "bound again");
    Check(LargestChannelChange(offFrame.shown, onFrame.shown) <= 1 && watched.debugPasses == 0 && onFrame.rendered &&
              onFrame.statesKept,
          "ClientShadowMaps=1 leaves the picture unchanged at DebugView 0");
    Check(first.nearRefsInTheFrame == nearRefs + 1 && nearRefsAfter == nearRefs &&
              first.inTheFrame.heldTextures == kTestMaps && watched.heldTextures == 0,
          "client shadow maps: each map found is held for the frame only and released at Present");

    const bool mapsOk = f.mapCount == kTestMaps && f.maps[0].texture == o.maps[0] && f.maps[1].texture == o.maps[1] &&
                        f.maps[2].texture == o.maps[2] && f.maps[0].size == kClientMapSize &&
                        f.maps[1].size == kClientMapSize && f.maps[2].size == kClientDirectMapSize &&
                        f.maps[0].format == D3DFMT_D24X8 && f.maps[1].format == D3DFMT_D24X8 &&
                        f.maps[2].format == D3DFMT_D24X8;
    const ClientShadowMap& cached = f.maps[kCachedMap];
    const bool cachedOk = cached.texture == o.maps[kCachedMap] && cached.size == kClientDirectMapSize &&
                          cached.format == D3DFMT_D24X8 && cached.casterDraws == 0 && !cached.hasPalette &&
                          !cached.hasDirect && f.mapCount == kTestMaps && f.terrain[0].stageMaps[3] == -1 &&
                          f.models[1].stageMaps[2] == -1 && f.models[1].stageMaps[3] == -1;
    const bool castersOk = f.maps[0].casterDraws == 1 && f.maps[0].paletteDraws == 1 && f.maps[1].casterDraws == 3 &&
                           f.maps[1].paletteDraws == 3 && f.maps[2].casterDraws == 2 && f.maps[2].directDraws == 1 &&
                           f.maps[2].paletteDraws == 0 && !f.maps[2].hasPalette && f.casterDrawsElsewhere == 1 &&
                           f.maps[0].paletteVs == Fnv1a(g_vs_test_caster, sizeof(g_vs_test_caster));
    Check(mapsOk && castersOk,
          "client shadow maps: the square depth targets drawn with caster shaders are found with their size and "
          "format; caster draws into other targets are counted apart");
    Check(cachedOk, "client shadow maps: a square depth texture a receiver binds without a caster drawing into it "
                    "this frame is kept as a map drawn earlier; colour textures and a non-square depth texture on "
                    "receiver stages are not");
    const float nearError = MatrixDifference(&f.maps[0].lightViewProjection[0][0], s.lightViewProjection[0], 4);
    const float farError = MatrixDifference(&f.maps[1].lightViewProjection[0][0], s.lightViewProjection[1], 4);
    const float directError = MatrixDifference(&f.maps[2].directProjection[0][0], s.projection[0], 4);
    std::printf("     light view-projection from the caster uploads: near map off by %.2g, far map by %.2g; direct "
                "caster projection off by %.2g\n",
                nearError, farError, directError);
    Check(f.maps[0].hasPalette && f.maps[1].hasPalette && f.maps[2].hasDirect &&
              nearError < kClientShadowMatrixTolerance && farError < kClientShadowMatrixTolerance &&
              directError < kClientShadowMatrixTolerance,
          "client shadow maps: the light view-projection is c2-5 times c14-16 of the first caster draw");
    const ClientShadowReceiver& terrain = f.terrain[0];
    const ClientShadowReceiver& models = f.models[1];
    const bool receiversOk =
        terrain.draws == 1 && models.draws == 1 && f.terrain[1].draws == 0 && f.models[0].draws == 0 &&
        terrain.stageMaps[0] == 0 && terrain.stageMaps[1] == 1 && terrain.stageMaps[2] == kCachedMap &&
        terrain.stageMaps[3] == -1 && models.stageMaps[0] == 1 && models.stageMaps[1] == 0 &&
        models.stageMaps[2] == -1 && models.stageMaps[3] == -1 && f.receiverDrawsWithoutMap == 0 &&
        RowsDifference(&terrain.rows[0][0], s.terrainRows, kClientShadowRows) == 0.0f &&
        RowsDifference(&models.rows[0][0], s.modelRows, kClientShadowRows) == 0.0f &&
        terrain.vs == Fnv1a(g_vs_test_terrain_receiver, sizeof(g_vs_test_terrain_receiver)) &&
        models.vs == Fnv1a(g_vs_test_model_receiver, sizeof(g_vs_test_model_receiver));
    Check(receiversOk, "client shadow maps: the receivers' rows (c37-48 terrain, c224-235 models) and the maps on "
                       "their stages are recorded");

    const std::string text = line;
    const std::vector<float> angles = LoggedLightAngles(text);
    const bool lineOk =
        text.rfind("client shadow maps: 4 in this frame; m0 2048x2048 D24X8: 1 casters (1 palette, 0 direct, vs ", 0) ==
            0 &&
        text.find("; m3 1024x1024 D24X8: not drawn in this frame, bound for receivers; ") != std::string::npos &&
        text.find("), orthographic 60x60 yd, 1000 yd deep") != std::string::npos &&
        text.find("m1 2048x2048 D24X8: 3 casters (3 palette, 0 direct") != std::string::npos &&
        text.find("), orthographic 140x140 yd") != std::string::npos &&
        text.find("m2 1024x1024 D24X8: 2 casters (0 palette, 1 direct), no camera-to-light matrix") !=
            std::string::npos &&
        ReceiverRowsMatch(text, "terrain vs ", "with m0 on s5 (s5-s8: m0 m1 m3 -), 1 draws") &&
        ReceiverRowsMatch(text, "models vs ", "with m1 on s4 (s4-s7: m1 m0 - -), 1 draws") &&
        text.find("1 caster draws into other targets, 0 receiver draws without a map") != std::string::npos;
    Check(lineOk && angles.size() == 2 && angles[0] < kClientShadowLightAngleTolerance &&
              angles[1] < kClientShadowLightAngleTolerance && watched.foundLogged >= 1,
          "client shadow maps: the log line names each map, its casters, extent and light direction, and "
          "compares the receivers' rows with the casters'");

    Config receiversView = on;
    receiversView.debugView = kDebugViewClientShadowReceivers;
    SetTestConfig(&receiversView);
    const ClientShadowFrameResult byReceivers = DrawClientShadowFrame(h, o, s, kEverything);
    SavePng(outDir + L"\\debug-client-shadows-receivers.png", byReceivers.shown.w, byReceivers.shown.h,
            byReceivers.shown.bgra);
    Check(byReceivers.rendered && byReceivers.statesKept && TintsMatch(byReceivers, s, "view 7", 0),
          "DebugView 7: the client's maps, projected with the terrain receivers' rows, shade the ground where the "
          "casters stand between it and the light, use the map drawn earlier, and mark ground outside every map");
    const ClientShadowFrameResult byModels = DrawClientShadowFrame(h, o, s, kCasters | kModelReceivers);
    Check(byModels.rendered && TintsMatch(byModels, s, "view 7, model receivers only", 1),
          "DebugView 7 falls back to the model receivers' rows and keeps their order of maps");
    Config castersView = on;
    castersView.debugView = kDebugViewClientShadowCasters;
    SetTestConfig(&castersView);
    const ClientShadowFrameResult byCasters = DrawClientShadowFrame(h, o, s, kEverything);
    SavePng(outDir + L"\\debug-client-shadows-casters.png", byCasters.shown.w, byCasters.shown.h,
            byCasters.shown.bgra);
    Check(byCasters.rendered && byCasters.statesKept && TintsMatch(byCasters, s, "view 8", 2),
          "DebugView 8: the client's maps, projected with the casters' c2-5 times c14-16, shade the same ground");
    const ClientShadowStats views = ClientShadowStatsAndReset();
    Check(views.debugPasses == 3, "the client shadow views draw one pass per frame");

    SetTestConfig(&off);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    Config emptyView = off;
    emptyView.debugView = kDebugViewClientShadowReceivers;
    SetTestConfig(&emptyView);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    ClientShadowStatsAndReset();
    ClientShadowFrameResult empty;
    for (int frame = 0; frame < kClientShadowSettleFrames; ++frame)
        empty = DrawClientShadowFrame(h, o, s, 0);
    const ClientShadowStats none = ClientShadowStatsAndReset();
    vf_test_client_shadow_log(line, sizeof(line));
    std::printf("%s\n", line);
    Check(empty.rendered && TintsMatch(empty, s, "view 7 without casters", 3) && none.noneLogged == 1 &&
              none.foundLogged == 0 && none.framesWatched == kClientShadowSettleFrames &&
              std::string(line) == "client shadow maps: none in this frame (0 caster draws into other targets, 0 "
                                   "receiver draws without a map); at extShadowQuality 0 the client draws none",
          "DebugView 7 watches even with ClientShadowMaps=0; without casters it marks the ground and logs "
          "\"none\" once");

    SetTestConfig(&on);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    h.BeginFrame();
    DrawClientCasters(h.dev, o, s, false);
    h.dev->EndScene();
    ClientShadowStats unfinished = {};
    vf_test_client_shadow_stats(&unfinished, 0);
    o.Release();
    const HRESULT reset = h.dev->Reset(&h.pp);
    const ClientShadowStats afterReset = ClientShadowStatsAndReset();
    std::printf("     Reset with %u maps held in an unfinished frame: 0x%08lX, %u held after it\n",
                unfinished.heldTextures, static_cast<unsigned long>(reset), afterReset.heldTextures);
    Check(unfinished.heldTextures == 3 && SUCCEEDED(reset) && afterReset.heldTextures == 0,
          "a Reset in the middle of a watched frame releases the held maps first and succeeds");

    SetClientShaderRoles(0);
    SetTestConfig(&start);
    h.dev->Present(nullptr, nullptr, nullptr, nullptr);
    ClientShadowStatsAndReset();
}

const char* ClientShaderRoleName(int role)
{
    switch (role)
    {
    case kDirectCasterRole:
        return "direct-caster";
    case kPaletteCasterRole:
        return "palette-caster";
    case kCasterPixelRole:
        return "caster-pixel";
    default:
        return "-";
    }
}

int ClassifyShaderFiles(int count, wchar_t** paths)
{
    int files = 0;
    auto classify = [&files](const std::wstring& path) {
        const std::string bytes = ReadText(path);
        if (bytes.size() < sizeof(DWORD))
            return;
        std::vector<DWORD> code(bytes.size() / sizeof(DWORD));
        std::memcpy(code.data(), bytes.data(), code.size() * sizeof(DWORD));
        const bool pixel = (code[0] & 0xFFFF0000u) == 0xFFFF0000u;
        const unsigned reads = vf_test_client_shader_reads(code.data(), static_cast<unsigned>(bytes.size()));
        const unsigned long long hash = Fnv1a(bytes.data(), bytes.size());
        std::printf("%s %s_%lu_%lu %-14s%s%s %ls\n", Hex16(hash).c_str(), pixel ? "ps" : "vs",
                    static_cast<unsigned long>(D3DSHADER_VERSION_MAJOR(code[0])),
                    static_cast<unsigned long>(D3DSHADER_VERSION_MINOR(code[0])),
                    ClientShaderRoleName(vf_test_client_shader_role(hash)),
                    reads & kReadsModelReceiverRows ? " model-receiver" : "",
                    reads & kReadsTerrainReceiverRows ? " terrain-receiver" : "", path.c_str());
        ++files;
    };
    for (int i = 0; i < count; ++i)
    {
        const std::wstring path = paths[i];
        const DWORD attributes = GetFileAttributesW(path.c_str());
        if (attributes == INVALID_FILE_ATTRIBUTES)
            continue;
        if (!(attributes & FILE_ATTRIBUTE_DIRECTORY))
        {
            classify(path);
            continue;
        }
        WIN32_FIND_DATAW found = {};
        HANDLE find = FindFirstFileW((path + L"\\*.bin").c_str(), &found);
        if (find == INVALID_HANDLE_VALUE)
            continue;
        do
            classify(path + L"\\" + found.cFileName);
        while (FindNextFileW(find, &found));
        FindClose(find);
    }
    std::printf("%d shader files\n", files);
    return files ? 0 : 1;
}

constexpr uint32_t kOpTexld = 66;
constexpr uint32_t kOpDsx = 91;
constexpr uint32_t kOpDsy = 92;
constexpr uint32_t kOpTexldd = 93;
constexpr uint32_t kOpDclToken = 31;
constexpr uint32_t kOpCommentToken = 0xFFFE;
constexpr uint32_t kShaderEndToken = 0x0000FFFF;
constexpr uint32_t kTexcoordUsage = 5;
constexpr uint32_t kViewPositionTexcoord = 3;

struct ShaderCensus
{
    int texld = 0;
    int texldd = 0;
    int dsx = 0;
    int dsy = 0;
    bool viewPositionInput = false;
    bool ended = false;
    int highestSampler = -1;
    int colourWrites[4] = {};
};

constexpr uint32_t kOpDefToken = 0x51u;
constexpr uint32_t kOpDefiToken = 0x30u;
constexpr uint32_t kOpDefbToken = 0x2Fu;
constexpr uint32_t kColourOutType = 8u;

ShaderCensus CountShader(const DWORD* code, size_t words)
{
    ShaderCensus c;
    size_t at = 1;
    while (at < words)
    {
        const uint32_t token = code[at];
        if (token == kShaderEndToken)
        {
            c.ended = true;
            break;
        }
        const uint32_t op = token & 0xFFFFu;
        if (op == kOpCommentToken)
        {
            at += 1 + ((token >> 16) & 0x7FFFu);
            continue;
        }
        const uint32_t length = (token >> 24) & 0xFu;
        if (op != kOpDclToken && op != kOpDefToken && op != kOpDefiToken && op != kOpDefbToken)
            for (uint32_t k = 1; k <= length && at + k < words; ++k)
            {
                const uint32_t reg = code[at + k];
                const uint32_t type = ((reg >> 28) & 7u) | ((reg >> 8) & 0x18u);
                if (type == kColourOutType && (reg & 0x7FFu) < 4)
                    ++c.colourWrites[reg & 0x7FFu];
            }
        if (op == kOpTexld)
            ++c.texld;
        else if (op == kOpTexldd)
            ++c.texldd;
        else if (op == kOpDsx)
            ++c.dsx;
        else if (op == kOpDsy)
            ++c.dsy;
        else if (op == kOpDclToken && at + 2 < words)
        {
            const uint32_t usage = code[at + 1];
            const uint32_t reg = code[at + 2];
            const uint32_t type = ((reg >> 28) & 7u) | ((reg >> 8) & 0x18u);
            if (type == 1u && (usage & 0x1Fu) == kTexcoordUsage && ((usage >> 16) & 0xFu) == kViewPositionTexcoord)
                c.viewPositionInput = true;
            if (type == 10u)
                c.highestSampler = std::max(c.highestSampler, static_cast<int>(reg & 0x7FFu));
        }
        at += 1 + length;
    }
    return c;
}

void CheckReliefReach()
{
    const Vec3 eye = {100.0f, 200.0f, 50.0f};
    const Vec3 f = Norm(Vec3{0.3f, 0.9f, -0.4f});
    const Vec3 r = Norm(Cross(f, kWorldUp));
    const Vec3 u = Cross(r, f);
    const Vec3 rows[3] = {r, u, f};
    float modelView[4][4] = {};
    for (int axis = 0; axis < 3; ++axis)
        for (int row = 0; row < 3; ++row)
            modelView[axis][row] = (&rows[row].x)[axis];
    modelView[3][0] = -Dot(r, eye);
    modelView[3][1] = -Dot(u, eye);
    modelView[3][2] = -Dot(f, eye);
    modelView[3][3] = 1.0f;
    const float near30[4] = {130.0f, 200.0f, 0.0f, 0.0f};
    const float behind80[4] = {100.0f, 120.0f, 0.0f, 0.0f};
    const float far100[4] = {100.0f, 300.0f, -40.0f, 0.0f};
    const bool a = ChunkWithinReach(modelView, near30, 40.0f);
    const bool b = ChunkWithinReach(modelView, behind80, 40.0f);
    const bool c = ChunkWithinReach(modelView, far100, 40.0f);
    const bool d = ChunkWithinReach(modelView, far100, 60.0f);
    std::printf("     chunks within the relief's reach at 40 yd: 30 yd away %d, 80 yd behind %d, 100 yd ahead %d (%d at "
                "60 yd)\n",
                a ? 1 : 0, b ? 1 : 0, c ? 1 : 0, d ? 1 : 0);
    Check(a && b && !c && d, "relief: a chunk is drawn with relief only while its corner is within the distance plus "
                             "a chunk's diagonal");
}
ShaderCode CodeOf(const void* bytes, size_t size)
{
    ShaderCode code;
    code.words = static_cast<const uint32_t*>(bytes);
    code.count = size / 4;
    return code;
}

ShaderCode ReliefFragment(int layers)
{
    switch (layers)
    {
    case 1:
        return CodeOf(g_ps_relief_1, sizeof g_ps_relief_1);
    case 2:
        return CodeOf(g_ps_relief_2, sizeof g_ps_relief_2);
    case 3:
        return CodeOf(g_ps_relief_3, sizeof g_ps_relief_3);
    default:
        return CodeOf(g_ps_relief_4, sizeof g_ps_relief_4);
    }
}

ShaderCode TerrainFragment(int layers, unsigned mode)
{
    const int i = std::clamp(layers, 1, kReliefMaxLayers) - 1;
    const ShaderCode material[kReliefMaxLayers] = {
        CodeOf(g_ps_material_1, sizeof g_ps_material_1), CodeOf(g_ps_material_2, sizeof g_ps_material_2),
        CodeOf(g_ps_material_3, sizeof g_ps_material_3), CodeOf(g_ps_material_4, sizeof g_ps_material_4)};
    const ShaderCode both[kReliefMaxLayers] = {CodeOf(g_ps_relief_material_1, sizeof g_ps_relief_material_1),
                                               CodeOf(g_ps_relief_material_2, sizeof g_ps_relief_material_2),
                                               CodeOf(g_ps_relief_material_3, sizeof g_ps_relief_material_3),
                                               CodeOf(g_ps_relief_material_4, sizeof g_ps_relief_material_4)};
    if (mode == kSpliceMaterial)
        return material[i];
    if (mode == (kSpliceRelief | kSpliceMaterial))
        return both[i];
    return ReliefFragment(layers);
}

ShaderCode TestTerrainPixelShader(int layers)
{
    switch (layers)
    {
    case 1:
        return CodeOf(g_ps_test_terrain_1, sizeof g_ps_test_terrain_1);
    case 2:
        return CodeOf(g_ps_test_terrain_2, sizeof g_ps_test_terrain_2);
    case 3:
        return CodeOf(g_ps_test_terrain_3, sizeof g_ps_test_terrain_3);
    default:
        return CodeOf(g_ps_test_terrain_4, sizeof g_ps_test_terrain_4);
    }
}

int UndeclaredInputReads(const uint32_t* words, size_t count)
{
    uint32_t declared[16] = {};
    int undeclared = 0;
    for (size_t at = 1; at < count && words[at] != kShaderEndToken;)
    {
        const uint32_t token = words[at];
        const uint32_t op = token & 0xFFFFu;
        if (op == kOpCommentToken)
        {
            at += 1 + ((token >> 16) & 0x7FFFu);
            continue;
        }
        const uint32_t length = (token >> 24) & 0xFu;
        const auto typeOf = [](uint32_t t) { return ((t >> 28) & 7u) | ((t >> 8) & 0x18u); };
        if (op == kOpDclToken && at + 2 < count && typeOf(words[at + 2]) == 1u)
            declared[words[at + 2] & 0xFu] |= (words[at + 2] >> 16) & 0xFu;
        const bool componentWise = op == 0x01u || op == 0x02u || op == 0x04u || op == 0x05u || op == 0x5Bu ||
                                   op == 0x5Cu;
        if (componentWise && length >= 2)
        {
            const uint32_t mask = (words[at + 1] >> 16) & 0xFu;
            for (uint32_t k = 2; k <= length && at + k < count; ++k)
            {
                const uint32_t source = words[at + k];
                if (typeOf(source) != 1u)
                    continue;
                uint32_t read = 0;
                for (int c = 0; c < 4; ++c)
                    if (mask & (1u << c))
                        read |= 1u << ((source >> (16 + 2 * c)) & 3u);
                if (read & ~declared[source & 0xFu])
                    ++undeclared;
            }
        }
        at += 1 + length;
    }
    return undeclared;
}

void CheckTerrainShaderSplice()
{
    for (int layers = 1; layers <= kReliefMaxLayers; ++layers)
    {
        const ShaderCode client = TestTerrainPixelShader(layers);
        TerrainPixelLayout layout;
        std::string why;
        const bool read = ReadTerrainPixelLayout(client, layout, &why);
        const int alpha = layers == 1 ? -1 : layers;
        std::printf("     %d-layer terrain shader: %s, %d layers, alpha map on s%d, COLOR0 in v%d, inputs to v%d, "
                    "temps to r%d\n",
                    layers, read ? "read" : why.c_str(), layout.layers, layout.alphaSampler, layout.colourInput,
                    layout.highestInput, layout.highestTemp);
        char what[160];
        std::snprintf(what, sizeof what, "relief: a %d-layer terrain shader is read as %d layers, alpha map on s%d",
                      layers, layers, alpha);
        Check(read && layout.layers == layers && layout.alphaSampler == alpha && layout.colourInput == 0 &&
                  !layout.viewPositionDeclared,
              what);

        std::vector<uint32_t> spliced;
        const bool ok = SpliceTerrainRelief(client, ReliefFragment(layers), spliced, &why);
        const ShaderCensus before = CountShader(reinterpret_cast<const DWORD*>(client.words), client.count);
        const ShaderCensus after = ok ? CountShader(reinterpret_cast<const DWORD*>(spliced.data()), spliced.size())
                                      : ShaderCensus{};
        const ShaderCensus fragment =
            CountShader(reinterpret_cast<const DWORD*>(ReliefFragment(layers).words), ReliefFragment(layers).count);
        const int fetches = layers == 1 ? 1 : layers + 1;
        std::printf("     spliced: %s, %zu words; texld %d -> %d, texldd %d, dsx %d, dsy %d, view position input %d, "
                    "samplers to s%d\n",
                    ok ? "ok" : why.c_str(), spliced.size(), before.texld, after.texld, after.texldd, after.dsx,
                    after.dsy, after.viewPositionInput ? 1 : 0, after.highestSampler);
        std::snprintf(what, sizeof what,
                      "relief: the %d-layer shader is spliced: its %d layer fetches take the offset with their own "
                      "gradients, the view position is read, heights on s9-s%d",
                      layers, layers, kReliefFirstHeightSampler + layers - 1);
        Check(ok && after.ended && after.texldd == fragment.texldd + layers &&
                  after.texld == before.texld - layers + fragment.texld &&
                  after.dsx == fragment.dsx + layers && after.dsy == fragment.dsy + layers &&
                  after.viewPositionInput && after.highestSampler == kReliefFirstHeightSampler + layers - 1 &&
                  fetches == before.texld,
              what);

        const int clientReads = UndeclaredInputReads(client.words, client.count);
        const int splicedReads = ok ? UndeclaredInputReads(spliced.data(), spliced.size()) : -1;
        std::printf("     input components read but not declared: client %d, spliced %d\n", clientReads,
                    splicedReads);
        std::snprintf(what, sizeof what,
                      "relief: the %d-layer shader's added instructions read only the input components it declares",
                      layers);
        Check(clientReads == 0 && splicedReads == 0, what);
    }

    std::vector<uint32_t> spliced;
    std::string why;
    const bool mismatched = SpliceTerrainRelief(TestTerrainPixelShader(2), ReliefFragment(4), spliced, &why);
    std::printf("     a 2-layer shader with the 4-layer fragment: %s\n", mismatched ? "spliced" : why.c_str());
    Check(!mismatched, "relief: a fragment for more layers than the shader has is refused");

    TerrainPixelLayout layout;
    const bool composite = ReadTerrainPixelLayout(CodeOf(g_ps_test_replay, sizeof g_ps_test_replay), layout, &why);
    const bool caster = ReadTerrainPixelLayout(CodeOf(g_ps_test_caster, sizeof g_ps_test_caster), layout, &why);
    const bool vertex = ReadTerrainPixelLayout(CodeOf(g_vs_test_terrain_4, sizeof g_vs_test_terrain_4), layout, &why);
    std::printf("     read as terrain: replay pixel shader %d, caster pixel shader %d, a vertex shader %d\n",
                composite ? 1 : 0, caster ? 1 : 0, vertex ? 1 : 0);
    Check(!composite && !caster && !vertex, "relief: shaders that are not terrain pixel shaders are left alone");

    std::vector<uint32_t> tooMany(TestTerrainPixelShader(1).words,
                                  TestTerrainPixelShader(1).words + TestTerrainPixelShader(1).count);
    bool raised = false;
    for (size_t at = 1; at + 1 < tooMany.size(); ++at)
    {
        const uint32_t op = tooMany[at] & 0xFFFFu;
        if (op == kOpCommentToken)
        {
            at += (tooMany[at] >> 16) & 0x7FFFu;
            continue;
        }
        if (op == kOpTexld)
        {
            tooMany[at + 1] = (tooMany[at + 1] & ~0x7FFu) | 30u;
            raised = true;
            break;
        }
        at += (tooMany[at] >> 24) & 0xFu;
    }
    const bool highTemps = raised && SpliceTerrainRelief({tooMany.data(), tooMany.size()}, ReliefFragment(1), spliced, &why);
    std::printf("     a shader writing r30: %s\n", highTemps ? "spliced" : why.c_str());
    Check(raised && !highTemps, "relief: a shader without spare temporary registers is refused");

    std::vector<uint32_t> highConstant(TestTerrainPixelShader(1).words,
                                       TestTerrainPixelShader(1).words + TestTerrainPixelShader(1).count);
    bool moved = false;
    for (size_t at = 1; at < highConstant.size() && !moved; ++at)
    {
        const uint32_t token = highConstant[at];
        const uint32_t op = token & 0xFFFFu;
        if (op == kOpCommentToken)
        {
            at += (token >> 16) & 0x7FFFu;
            continue;
        }
        const uint32_t length = (token >> 24) & 0xFu;
        if (op != kOpDclToken && op != 81u && op != kShaderEndToken)
            for (uint32_t k = 2; k <= length && at + k < highConstant.size(); ++k)
            {
                uint32_t& source = highConstant[at + k];
                const uint32_t type = ((source >> 28) & 7u) | ((source >> 8) & 0x18u);
                if (type == 2u && (source & 0x7FFu) < kReliefLiteralBase)
                {
                    source = (source & ~0x7FFu) | 190u;
                    moved = true;
                    break;
                }
            }
        at += length;
    }
    const bool highConstants =
        moved && SpliceTerrainRelief({highConstant.data(), highConstant.size()}, ReliefFragment(1), spliced, &why);
    std::printf("     a shader reading c190: %s\n", highConstants ? "spliced" : why.c_str());
    Check(moved && !highConstants, "relief: a shader reading the constants the relief uses is refused");

    const bool viewed = VertexShaderWritesViewPosition(CodeOf(g_vs_test_terrain_4, sizeof g_vs_test_terrain_4));
    const bool notViewed =
        VertexShaderWritesViewPosition(CodeOf(g_vs_test_terrain_no_view, sizeof g_vs_test_terrain_no_view));
    const bool receiver =
        VertexShaderWritesViewPosition(CodeOf(g_vs_test_terrain_receiver, sizeof g_vs_test_terrain_receiver));
    std::printf("     vertex shaders writing the view position: terrain %d, terrain without it %d, receiver %d\n",
                viewed ? 1 : 0, notViewed ? 1 : 0, receiver ? 1 : 0);
    Check(viewed && !notViewed && !receiver, "relief: vertex shaders writing the view position to TEXCOORD3 are found");
}

std::vector<uint8_t> ReliefPack(const std::vector<relieffile::Entry>& entries, uint32_t heights, uint32_t size,
                                uint32_t levels)
{
    relieffile::Header h = {};
    std::memcpy(h.magic, relieffile::kMagic, 4);
    h.version = relieffile::kVersion;
    h.entryCount = static_cast<uint32_t>(entries.size());
    h.heightCount = heights;
    h.heightSize = size;
    h.levelCount = levels;
    h.heightBytes = relieffile::LevelBytes(size, levels);
    std::vector<uint8_t> out(sizeof h);
    std::memcpy(out.data(), &h, sizeof h);
    for (const relieffile::Entry& e : entries)
    {
        const auto* p = reinterpret_cast<const uint8_t*>(&e);
        out.insert(out.end(), p, p + sizeof e);
    }
    for (uint32_t k = 0; k < heights; ++k)
        for (uint32_t i = 0; i < h.heightBytes; ++i)
            out.push_back(static_cast<uint8_t>(k * 50 + i % 7));
    return out;
}

std::vector<uint8_t> ReliefPackVersionOne(const std::vector<relieffile::EntryVersionOne>& entries, uint32_t heights,
                                          uint32_t size, uint32_t levels)
{
    relieffile::Header h = {};
    std::memcpy(h.magic, relieffile::kMagic, 4);
    h.version = relieffile::kVersionOne;
    h.entryCount = static_cast<uint32_t>(entries.size());
    h.heightCount = heights;
    h.heightSize = size;
    h.levelCount = levels;
    h.heightBytes = relieffile::LevelBytes(size, levels);
    std::vector<uint8_t> out(sizeof h);
    std::memcpy(out.data(), &h, sizeof h);
    for (const relieffile::EntryVersionOne& e : entries)
    {
        const auto* p = reinterpret_cast<const uint8_t*>(&e);
        out.insert(out.end(), p, p + sizeof e);
    }
    for (uint32_t k = 0; k < heights; ++k)
        for (uint32_t i = 0; i < h.heightBytes; ++i)
            out.push_back(static_cast<uint8_t>(k * 50 + i % 7));
    return out;
}

void CheckReliefCatalog()
{
    Check(relieffile::HashedLevel(1024, 1024, 11) == 4 && relieffile::HashedLevel(512, 512, 10) == 3 &&
              relieffile::HashedLevel(1024, 1024, 9) == 4 && relieffile::HashedLevel(32, 32, 6) == 0 &&
              relieffile::HashedLevel(256, 512, 10) == 3 && relieffile::HashedLevel(1024, 1024, 3) == 2,
          "relief: the hashed mip level is the first one no larger than 64 texels");
    Check(relieffile::RowBytes(relieffile::kFormatDxt1, 64) == 128 &&
              relieffile::RowBytes(relieffile::kFormatDxt5, 64) == 256 &&
              relieffile::RowBytes(relieffile::kFormatArgb, 64) == 256 &&
              relieffile::RowBytes(relieffile::kFormatDxt3, 2) == 16 &&
              relieffile::RowCount(relieffile::kFormatDxt1, 2) == 1 &&
              relieffile::RowCount(relieffile::kFormatArgb, 2) == 2 && relieffile::RowBytes(22u, 64) == 0,
          "relief: rows of DXT1/3/5 blocks and ARGB texels are hashed as stored");
    const uint8_t sample[] = {1, 2, 3};
    Check(relieffile::Fnv1a(sample, 3) == relieffile::Fnv1a(sample + 1, 2, relieffile::Fnv1a(sample, 1)) &&
              relieffile::Fnv1a(nullptr, 0) == 14695981039346656037ull,
          "relief: hashing a level row by row equals hashing it whole");

    std::vector<relieffile::Entry> entries = {
        {0x10ull, relieffile::kFormatDxt5, 64, 64, 1, 1.0f, reliefclass::kRoads},
        {0x20ull, relieffile::kFormatDxt1, 64, 64, 0, 0.5f, reliefclass::kGrass},
        {0x20ull, relieffile::kFormatDxt5, 64, 64, 1, 0.25f, reliefclass::kRock},
        {0x20ull, relieffile::kFormatDxt5, 64, 128, 0, 0.0f, reliefclass::kSand},
        {0x28ull, relieffile::kFormatDxt5, 64, 64, relieffile::kNoHeights, 0.75f, reliefclass::kBark},
    };
    const std::vector<uint8_t> good = ReliefPack(entries, 2, 16, 5);
    ReliefCatalog catalog;
    const bool parsed = catalog.Parse(good.data(), good.size(), "harness");
    const relieffile::Entry* a = catalog.Find(0x20ull, relieffile::kFormatDxt5, 64, 64);
    const relieffile::Entry* b = catalog.Find(0x20ull, relieffile::kFormatDxt3, 64, 64);
    const relieffile::Entry* c = catalog.Find(0x20ull, relieffile::kFormatDxt5, 32, 32);
    const relieffile::Entry* d = catalog.Find(0x30ull, relieffile::kFormatDxt5, 64, 64);
    const relieffile::Entry* typeOnly = catalog.Find(0x28ull, relieffile::kFormatDxt5, 64, 64);
    std::vector<uint8_t> heights;
    const bool readBack = a && catalog.ReadHeights(a->heightIndex, heights);
    const uint32_t bytes = relieffile::LevelBytes(16, 5);
    std::vector<uint8_t> none;
    const bool noHeightsRead = typeOnly && catalog.ReadHeights(typeOnly->heightIndex, none);
    std::printf("     version %u; a texture known by type alone: found %d, %s, flatness %.2f, heights %d, read %d\n",
                catalog.Version(), typeOnly ? 1 : 0, typeOnly ? reliefclass::Name(typeOnly->reliefClass) : "-",
                typeOnly ? typeOnly->flatness : -1.0f, typeOnly && relieffile::HasHeights(*typeOnly) ? 1 : 0,
                noHeightsRead ? 1 : 0);
    Check(parsed && catalog.Version() == 2 && catalog.EntryCount() == 5 && catalog.HeightSize() == 16 &&
              catalog.LevelCount() == 5 && a && a->flatness == 0.25f && a->reliefClass == reliefclass::kRock && !b &&
              !c && !d && readBack && heights.size() == bytes && heights[0] == 50 && heights[6] == 56 &&
              !catalog.ReadHeights(2, heights),
          "relief: the catalog finds a texture by hash, format and size, with its type, flatness and heights");
    Check(typeOnly && typeOnly->reliefClass == reliefclass::kBark && typeOnly->flatness == 0.75f &&
              !relieffile::HasHeights(*typeOnly) && !noHeightsRead,
          "relief: a texture can be known by its type alone, without a height map");

    std::vector<relieffile::Entry> unsorted = entries;
    std::swap(unsorted[0], unsorted[1]);
    std::vector<relieffile::Entry> outOfRange = entries;
    outOfRange[2].heightIndex = 2;
    std::vector<relieffile::Entry> negative = entries;
    negative[0].flatness = -0.1f;
    std::vector<relieffile::Entry> overOne = entries;
    overOne[0].flatness = 1.5f;
    std::vector<relieffile::Entry> unknownType = entries;
    unknownType[3].reliefClass = reliefclass::kCount;
    std::vector<relieffile::Entry> twice = entries;
    twice[1] = twice[2];
    std::vector<uint8_t> truncated = good;
    truncated.pop_back();
    std::vector<uint8_t> shortEntries(good.begin(), good.begin() + sizeof(relieffile::Header) + 40);
    std::vector<uint8_t> wrongBytes = good;
    reinterpret_cast<relieffile::Header*>(wrongBytes.data())->heightBytes += 1;
    std::vector<uint8_t> wrongMagic = good;
    wrongMagic[0] = 'X';
    std::vector<uint8_t> laterVersion = good;
    reinterpret_cast<relieffile::Header*>(laterVersion.data())->version = relieffile::kVersion + 1;
    ReliefCatalog bad;
    const bool refused[] = {
        !bad.Parse(ReliefPack(unsorted, 2, 16, 5).data(), ReliefPack(unsorted, 2, 16, 5).size(), "harness"),
        !bad.Parse(ReliefPack(outOfRange, 2, 16, 5).data(), ReliefPack(outOfRange, 2, 16, 5).size(), "harness"),
        !bad.Parse(ReliefPack(negative, 2, 16, 5).data(), ReliefPack(negative, 2, 16, 5).size(), "harness"),
        !bad.Parse(ReliefPack(overOne, 2, 16, 5).data(), ReliefPack(overOne, 2, 16, 5).size(), "harness"),
        !bad.Parse(ReliefPack(unknownType, 2, 16, 5).data(), ReliefPack(unknownType, 2, 16, 5).size(), "harness"),
        !bad.Parse(ReliefPack(twice, 2, 16, 5).data(), ReliefPack(twice, 2, 16, 5).size(), "harness"),
        !bad.Parse(truncated.data(), truncated.size(), "harness"),
        !bad.Parse(shortEntries.data(), shortEntries.size(), "harness"),
        !bad.Parse(wrongBytes.data(), wrongBytes.size(), "harness"),
        !bad.Parse(wrongMagic.data(), wrongMagic.size(), "harness"),
        !bad.Parse(laterVersion.data(), laterVersion.size(), "harness"),
    };
    std::printf("     refused: unsorted %d, height out of range %d, negative flatness %d, flatness over 1 %d, unknown "
                "type %d, a key twice %d, truncated %d, entries cut short %d, wrong level bytes %d, wrong magic %d, a "
                "later version %d; nothing loaded after a refusal %d\n",
                refused[0], refused[1], refused[2], refused[3], refused[4], refused[5], refused[6], refused[7],
                refused[8], refused[9], refused[10], bad.Loaded() ? 0 : 1);
    Check(std::all_of(std::begin(refused), std::end(refused), [](bool r) { return r; }) && !bad.Loaded(),
          "relief: a damaged or unsorted relief file is refused whole");

    struct OldTexture
    {
        float depth;
        uint8_t reliefClass;
    };
    const OldTexture old[] = {
        {1.0f, reliefclass::kRoads}, {0.6f, reliefclass::kDirt}, {0.3f, reliefclass::kSand},
        {0.4f, reliefclass::kGrass}, {0.7f, reliefclass::kDirt}, {0.42f, reliefclass::kDirt},
        {0.18f, reliefclass::kSand}, {0.0f, reliefclass::kSand}, {0.85f, reliefclass::kRoads},
    };
    std::vector<relieffile::EntryVersionOne> oldEntries;
    for (size_t k = 0; k < std::size(old); ++k)
        oldEntries.push_back({0x100ull + k, relieffile::kFormatDxt5, 64, 64, static_cast<uint32_t>(k % 2), old[k].depth});
    const std::vector<uint8_t> versionOne = ReliefPackVersionOne(oldEntries, 2, 16, 5);
    ReliefCatalog oldCatalog;
    const bool oldParsed = oldCatalog.Parse(versionOne.data(), versionOne.size(), "harness");
    const Config builtIn = {};
    bool mapped = oldParsed && oldCatalog.Version() == 1 && oldCatalog.EntryCount() == std::size(old);
    double worstDepth = 0.0;
    std::printf("     version 1 kinds read as:");
    for (size_t k = 0; k < std::size(old); ++k)
    {
        const relieffile::Entry* e = oldCatalog.Find(0x100ull + k, relieffile::kFormatDxt5, 64, 64);
        const float depth = e ? ReliefLayerDepth(builtIn, e->flatness, e->reliefClass) / builtIn.reliefDepth : -1.0f;
        std::printf(" %.2f %s (%.3f)", old[k].depth, e ? reliefclass::Name(e->reliefClass) : "-",
                    e ? e->flatness : -1.0f);
        mapped = mapped && e && e->reliefClass == old[k].reliefClass && e->heightIndex == k % 2;
        worstDepth = std::max(worstDepth, static_cast<double>(std::fabs(depth - old[k].depth)));
    }
    std::printf("; the depth at the built-in shares off by at most %.2g\n", worstDepth);
    Check(mapped && worstDepth < 1e-5, "relief: a version 1 file is read, each kind's depth turned into a type and "
                                       "flatness that give the same depth at the built-in shares");
    std::vector<relieffile::EntryVersionOne> oldUnsorted = oldEntries;
    std::swap(oldUnsorted[0], oldUnsorted[1]);
    std::vector<relieffile::EntryVersionOne> oldTypeOnly = oldEntries;
    oldTypeOnly[0].heightIndex = relieffile::kNoHeights;
    std::vector<relieffile::EntryVersionOne> oldTooDeep = oldEntries;
    oldTooDeep[0].depth = relieffile::kMaxVersionOneDepth + 1.0f;
    std::vector<relieffile::EntryVersionOne> oldNegative = oldEntries;
    oldNegative[0].depth = -0.5f;
    std::vector<uint8_t> oldTruncated = versionOne;
    oldTruncated.pop_back();
    ReliefCatalog oldBad;
    const bool oldRefused[] = {
        !oldBad.Parse(ReliefPackVersionOne(oldUnsorted, 2, 16, 5).data(),
                      ReliefPackVersionOne(oldUnsorted, 2, 16, 5).size(), "harness"),
        !oldBad.Parse(ReliefPackVersionOne(oldTypeOnly, 2, 16, 5).data(),
                      ReliefPackVersionOne(oldTypeOnly, 2, 16, 5).size(), "harness"),
        !oldBad.Parse(ReliefPackVersionOne(oldTooDeep, 2, 16, 5).data(),
                      ReliefPackVersionOne(oldTooDeep, 2, 16, 5).size(), "harness"),
        !oldBad.Parse(ReliefPackVersionOne(oldNegative, 2, 16, 5).data(),
                      ReliefPackVersionOne(oldNegative, 2, 16, 5).size(), "harness"),
        !oldBad.Parse(oldTruncated.data(), oldTruncated.size(), "harness"),
    };
    std::printf("     version 1 refused: unsorted %d, without heights %d, too deep %d, negative depth %d, truncated %d\n",
                oldRefused[0], oldRefused[1], oldRefused[2], oldRefused[3], oldRefused[4]);
    Check(std::all_of(std::begin(oldRefused), std::end(oldRefused), [](bool r) { return r; }) && !oldBad.Loaded(),
          "relief: a damaged version 1 file is refused whole, and it cannot hold textures without heights");
}

void CheckReliefFile(const std::wstring& outDir)
{
    const std::vector<relieffile::Entry> entries = {
        {0x10ull, relieffile::kFormatDxt5, 64, 64, 1, 1.0f, reliefclass::kWalls},
        {0x20ull, relieffile::kFormatDxt1, 64, 64, 0, 0.5f, reliefclass::kRoofs},
        {0x30ull, relieffile::kFormatDxt1, 64, 64, relieffile::kNoHeights, 0.5f, reliefclass::kCreatures},
    };
    const std::vector<uint8_t> pack = ReliefPack(entries, 2, 16, 5);
    const std::wstring path = FullPath(outDir + L"\\relief-file.bin");
    const bool written = WriteTestText(path, std::string(pack.begin(), pack.end()));
    ReliefCatalog catalog;
    const bool loaded = catalog.Load(NarrowPath(path));
    const relieffile::Entry* walls = catalog.Find(0x10ull, relieffile::kFormatDxt5, 64, 64);
    std::vector<uint8_t> before;
    const bool readBefore = walls && catalog.ReadHeights(walls->heightIndex, before);
    const uint64_t secondMap = sizeof(relieffile::Header) + entries.size() * sizeof(relieffile::Entry) +
                               static_cast<uint64_t>(relieffile::LevelBytes(16, 5));
    std::vector<uint8_t> changed = pack;
    changed[static_cast<size_t>(secondMap)] = 0xAB;
    const bool rewritten = WriteTestText(path, std::string(changed.begin(), changed.end()));
    std::vector<uint8_t> after;
    const bool readAfter = walls && catalog.ReadHeights(walls->heightIndex, after);
    std::vector<uint8_t> cut(pack.begin(), pack.end() - 1);
    const std::wstring cutPath = FullPath(outDir + L"\\relief-file-cut.bin");
    WriteTestText(cutPath, std::string(cut.begin(), cut.end()));
    ReliefCatalog cutCatalog;
    const bool cutLoaded = cutCatalog.Load(NarrowPath(cutPath));
    const std::vector<relieffile::Entry> typesOnly = {
        {0x40ull, relieffile::kFormatDxt5, 64, 64, relieffile::kNoHeights, 1.0f, reliefclass::kLeaves},
    };
    const std::vector<uint8_t> typesPack = ReliefPack(typesOnly, 0, 16, 5);
    const std::wstring typesPath = FullPath(outDir + L"\\relief-file-types.bin");
    WriteTestText(typesPath, std::string(typesPack.begin(), typesPack.end()));
    ReliefCatalog typesCatalog;
    const bool typesLoaded = typesCatalog.Load(NarrowPath(typesPath));
    std::printf("     from a file: loaded %d, %zu textures, %u height maps, the walls' first height %d; after the file "
                "changed on disk %d; a file cut short loaded %d; a file of types alone loaded %d with %zu texture\n",
                loaded ? 1 : 0, catalog.EntryCount(), catalog.HeightCount(), readBefore ? before[0] : -1,
                readAfter ? after[0] : -1, cutLoaded ? 1 : 0, typesLoaded ? 1 : 0, typesCatalog.EntryCount());
    Check(written && rewritten && loaded && catalog.EntryCount() == 3 && walls && readBefore && before[0] == 50 &&
              readAfter && after[0] == 0xAB,
          "relief: a file's heights are read from the disk when a texture needs them, not kept in memory");
    Check(!cutLoaded && typesLoaded && typesCatalog.EntryCount() == 1,
          "relief: a file cut short is refused, a file of types alone is read");
}

struct RuntimeImage
{
    int w = 0;
    int h = 0;
    std::vector<uint8_t> rgba;
    void Fill(int width, int height, uint8_t r, uint8_t g, uint8_t b, uint8_t a)
    {
        w = width;
        h = height;
        rgba.assign(static_cast<size_t>(w) * h * 4, 0);
        for (size_t i = 0; i < rgba.size(); i += 4)
            rgba[i] = r, rgba[i + 1] = g, rgba[i + 2] = b, rgba[i + 3] = a;
    }
    void Box(int x0, int y0, int x1, int y1, uint8_t r, uint8_t g, uint8_t b, uint8_t a)
    {
        for (int y = y0; y < y1; ++y)
            for (int x = x0; x < x1; ++x)
            {
                uint8_t* p = rgba.data() + (static_cast<size_t>(y) * w + x) * 4;
                p[0] = r, p[1] = g, p[2] = b, p[3] = a;
            }
    }
    void Noise(int x0, int y0, int x1, int y1, int low, int high, uint32_t seed)
    {
        for (int y = y0; y < y1; ++y)
            for (int x = x0; x < x1; ++x)
            {
                seed = seed * 1664525u + 1013904223u;
                const uint8_t v = static_cast<uint8_t>(low + static_cast<int>((seed >> 24) * (high - low + 1) / 256));
                uint8_t* p = rgba.data() + (static_cast<size_t>(y) * w + x) * 4;
                p[0] = p[1] = p[2] = v;
                p[3] = 255;
            }
    }
};

double RuntimeBoxMean(const runtimeheight::Result& r, int x0, int y0, int x1, int y1)
{
    double sum = 0.0;
    int n = 0;
    for (int y = y0; y < y1; ++y)
        for (int x = x0; x < x1; ++x, ++n)
            sum += r.height01[static_cast<size_t>(y) * r.width + x];
    return n ? sum / n : 0.0;
}

double RuntimeBoxRange(const runtimeheight::Result& r, int x0, int y0, int x1, int y1)
{
    float low = 1.0f;
    float high = 0.0f;
    for (int y = y0; y < y1; ++y)
        for (int x = x0; x < x1; ++x)
        {
            const float v = r.height01[static_cast<size_t>(y) * r.width + x];
            low = std::min(low, v);
            high = std::max(high, v);
        }
    return high >= low ? high - low : 0.0;
}

bool SameTexel(const std::vector<uint8_t>& rgba, size_t texel, int r, int g, int b, int a)
{
    if (rgba.size() < 4 * texel + 4)
        return false;
    const uint8_t* p = rgba.data() + 4 * texel;
    return std::abs(p[0] - r) <= 1 && std::abs(p[1] - g) <= 1 && std::abs(p[2] - b) <= 1 && p[3] == a;
}

void CheckRuntimeHeights()
{
    using namespace runtimeheight;
    std::vector<uint8_t> rgba;
    bool alpha = true;
    const uint8_t fourColour[8] = {0x00, 0xF8, 0x1F, 0x00, 0xE4, 0xE4, 0xE4, 0xE4};
    const bool dxt1 = Decode(D3DFMT_DXT1, 4, 4, fourColour, 8, rgba, alpha) && !alpha &&
                      SameTexel(rgba, 0, 255, 0, 0, 255) && SameTexel(rgba, 1, 0, 0, 255, 255) &&
                      SameTexel(rgba, 2, 170, 0, 85, 255) && SameTexel(rgba, 3, 85, 0, 170, 255) &&
                      SameTexel(rgba, 15, 85, 0, 170, 255);
    const uint8_t threeColour[8] = {0x1F, 0x00, 0x00, 0xF8, 0xE4, 0xE4, 0xE4, 0xE4};
    const bool dxt1Clear = Decode(D3DFMT_DXT1, 4, 4, threeColour, 8, rgba, alpha) && alpha &&
                           SameTexel(rgba, 2, 127, 0, 127, 255) && rgba[4 * 3 + 3] == 0;
    const uint8_t dxt5Block[16] = {255, 0, 0x88, 0x0E, 0, 0, 0, 0, 0xFF, 0xFF, 0xFF, 0xFF, 0, 0, 0, 0};
    const bool dxt5 = Decode(D3DFMT_DXT5, 4, 4, dxt5Block, 16, rgba, alpha) && alpha && rgba[3] == 255 &&
                      rgba[7] == 0 && rgba[11] == 219 && rgba[15] == 36 && rgba[0] == 255 && rgba[2] == 255;
    const uint8_t bgra[6] = {10, 20, 30, 40, 0xE0, 0x07};
    const bool argb = Decode(D3DFMT_A8R8G8B8, 1, 1, bgra, 4, rgba, alpha) && SameTexel(rgba, 0, 30, 20, 10, 40);
    const bool rgb565 = Decode(D3DFMT_R5G6B5, 1, 1, bgra + 4, 2, rgba, alpha) && SameTexel(rgba, 0, 0, 255, 0, 255);
    std::printf("     runtime heights, decoding: DXT1 %d, DXT1 with a clear texel %d, DXT5 alpha %d, A8R8G8B8 %d, "
                "R5G6B5 %d\n",
                dxt1 ? 1 : 0, dxt1Clear ? 1 : 0, dxt5 ? 1 : 0, argb ? 1 : 0, rgb565 ? 1 : 0);
    Check(dxt1 && dxt1Clear && dxt5 && argb && rgb565,
          "runtime heights: DXT1 (four and three colours), DXT5 alpha, A8R8G8B8 and R5G6B5 decode exactly");

    RuntimeImage flat;
    flat.Fill(64, 64, 128, 128, 128, 255);
    Result flatHeights;
    const bool flatMade = Make(flat.rgba.data(), 64, 64, false, DefaultWeights(), flatHeights);
    const bool allOne = flatMade && std::all_of(flatHeights.height01.begin(), flatHeights.height01.end(),
                                                [](float v) { return v == 1.0f; });
    Check(allOne && flatHeights.depthFactor == 0.0f,
          "runtime heights: a texture of one colour is flat and gets no depth");

    RuntimeImage stones;
    stones.Fill(64, 64, 60, 55, 50, 255);
    stones.Box(16, 16, 48, 48, 200, 190, 170, 255);
    Result stoneHeights;
    const bool stonesMade = Make(stones.rgba.data(), 64, 64, false, DefaultWeights(), stoneHeights);
    const double top = RuntimeBoxMean(stoneHeights, 20, 20, 44, 44);
    const double mortar = RuntimeBoxMean(stoneHeights, 0, 0, 8, 64);
    std::printf("     runtime heights, a bright stone on dark mortar: stone %.3f, mortar %.3f, depth factor %.3f\n", top,
                mortar, stoneHeights.depthFactor);
    Check(stonesMade && top - mortar > 0.3 && stoneHeights.depthFactor > 0.9,
          "runtime heights: a bright stone on dark mortar stands up and gets the full depth");

    RuntimeImage leaf;
    leaf.Fill(64, 64, 0, 0, 0, 0);
    leaf.Box(16, 0, 64, 64, 128, 128, 128, 255);
    Result guarded;
    Result unguarded;
    const bool leafMade = Make(leaf.rgba.data(), 64, 64, true, DefaultWeights(), guarded) &&
                          Make(leaf.rgba.data(), 64, 64, false, DefaultWeights(), unguarded);
    const double guardedRange = RuntimeBoxRange(guarded, 16, 0, 64, 64);
    const double unguardedRange = RuntimeBoxRange(unguarded, 16, 0, 64, 64);
    std::printf("     runtime heights, a cut-out leaf of one colour: cut out %d, depth factor %.3f, heights over the leaf "
                "%.3f apart; read without its alpha: depth factor %.3f, heights over the leaf %.3f apart\n",
                guarded.cutout ? 1 : 0, guarded.depthFactor, guardedRange, unguarded.depthFactor, unguardedRange);
    Check(leafMade && guarded.cutout && !unguarded.cutout && guarded.depthFactor == 0.0f && guardedRange < 0.001 &&
              unguarded.depthFactor > 0.9f && unguardedRange > 0.05,
          "runtime heights: a cut-out leaf of one colour stays flat and gets no depth, where its holes read as colour "
          "would give it a rim and the full depth");

    RuntimeImage strip;
    strip.Fill(64, 16, 90, 90, 90, 255);
    strip.Box(8, 4, 24, 12, 220, 220, 220, 255);
    Result wide;
    Result odd;
    const bool wideMade = Make(strip.rgba.data(), 64, 16, false, DefaultWeights(), wide) && wide.width == 64 &&
                          wide.height == 16 && RuntimeBoxMean(wide, 10, 6, 22, 10) > RuntimeBoxMean(wide, 40, 0, 64, 16);
    const bool oddRefused = !Make(strip.rgba.data(), 48, 16, false, DefaultWeights(), odd);
    unsigned levels = 0;
    const std::vector<uint8_t> l8 = L8Levels(stoneHeights, &levels);
    const bool levelsRight = levels == 7 && l8.size() == 5461;
    const bool working = WorkingLevel(512, 512, 10) == 1 && WorkingLevel(1024, 256, 11) == 2 &&
                         WorkingLevel(128, 128, 8) == 0 && WorkingLevel(512, 512, 1) == UINT32_MAX;
    Check(wideMade && oddRefused && levelsRight && working,
          "runtime heights: a 64x16 texture works, a side that is no power of two is refused, the mips go down to "
          "1x1, and the working level is the largest within 256");

    RuntimeImage big;
    big.Fill(256, 256, 0, 0, 0, 255);
    big.Noise(0, 0, 256, 256, 0, 255, 12345u);
    std::vector<double> times;
    for (int k = 0; k < 5; ++k)
    {
        Result r;
        const auto t0 = std::chrono::steady_clock::now();
        Make(big.rgba.data(), 256, 256, true, DefaultWeights(), r);
        times.push_back(std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - t0).count());
    }
    std::sort(times.begin(), times.end());
    std::printf("     runtime heights of a 256x256 texture: %.2f ms (median of 5, one core)\n", times[2]);
    Check(times[2] < 40.0, "runtime heights: a 256x256 texture takes under 40 ms on one core");
}

