    const bool everyType = std::all_of(std::begin(seen), std::end(seen), [](bool s) { return s; });
    std::printf("     %zu texture names, every type named %d\n", std::size(names), everyType ? 1 : 0);
    Check(all && everyType, "relief: texture types follow the name: folders first, then words, then the family");
